    "content": "谷歌为搭载谷歌内置系统的车辆推出改版后的车载谷歌应用商店，新增多款娱乐应用，YouTube上线一项新功能：车辆从驻车切换为行驶状态后，音频仍可持续播放。本次谷歌应用商店更新将在未来数周逐步推送。新版车载应用商店界面经过重新设计，新增Starz、火狐浏览器、Ludo King以及JioHotstar等应用，供驻车状态下使用。同时上线YouTube新功能，驻车观看视频的音频可在车辆行驶后继续播放。谷歌表示，搭载谷歌内置系统的车型覆盖16个品牌、超过100款车型。谷歌地图、Gemini等应用可直接在车机运行，无需连接手机…"
