    "content": "从相关企业人士处获悉，10月11日，通威股份、协鑫科技等头部光伏企业在杭州召开会议。此次会议透露出几项关键信息，一是进一步形成产能限制的落地计划，并通过市场化调节机制，推动各企业根据市场总需求自主统筹、主动压制自身产能；二是明确了一套相互监督机制——各企业达成一致，对违反国家低价倾销规定、恶意破坏市场经济规则、扰乱行业秩序的行为，鼓励主动举报。据悉，会议还就多晶硅及组件划出明确价格底线。其中，硅料平均成本含税价不得低于4.3万元/吨；BC组件价格不得低于0.86元/W，TOPCon组件不得低于0.79元/W。此外，…"
