    "pub_date": "2026-10-14 08:49:15",
    "author": "",
    "description": "随着防灾减灾能力不断提升，我国安全应急装备产业持续扩容。数据显示，2025年我国安全应急装备重点领域产业规模突破1万亿元，近三年年均增速保持10%以上。《安全应急装备产业发展“十五五”规划》提出，到2030年，安全应急装备重点领域产业规模目标达到1.4万亿元。",
    "content": "随着防灾减灾能力不断提升，我国安全应急装备产业持续扩容。数据显示，2025年我国安全应急装备重点领域产业规模突破1万亿元，近三年年均增速保持10%以上。《安全应急装备产业发展“十五五”规划》提出，到2030年，安全应急装备重点领域产业规模目标达到1.4万亿元。"
