    "pub_date": "2026-10-14 08:34:50",
    "author": "",
    "description": "中新社阿斯塔纳10月13日电 (记者 单璐)哈萨克斯坦副总理兼国民经济部长茹曼加林13日在政府会议上表示，今年前三季度，该国国内生产总值(GDP)同比增长4.2%。在石油减产等因素制约下，非资源型产业为该国经济增长提供了有力支撑。",
    "content": "中新社阿斯塔纳10月13日电 (记者 单璐)哈萨克斯坦副总理兼国民经济部长茹曼加林13日在政府会议上表示，今年前三季度，该国国内生产总值(GDP)同比增长4.2%。在石油减产等因素制约下，非资源型产业为该国经济增长提供了有力支撑。"
