    "author": "褚怡,杜哲宇,张豪夫",
    "description": "新华社柏林10月13日电（记者褚怡 杜哲宇 张豪夫）世界卫生峰会首席执行官卡斯滕·席克尔在2026年世界卫生峰会期间接受新华社记者专访时表示，全球卫生体系正面临多重危机，而中国在基层医疗、数字健康、卫生体系规模化发展以及国际卫生合作等方面的实践经验，可为构建更具韧性的全球卫生体系提供有益启示。 这是2026年10月12日在德国首都柏林拍摄的世界卫生峰会首席执行官卡斯滕·席克尔。新华社记者 张豪夫 摄 世界卫生峰会从2009年起每年在柏林…",
    "content": "新华社柏林10月13日电（记者褚怡 杜哲宇 张豪夫）世界卫生峰会首席执行官卡斯滕·席克尔在2026年世界卫生峰会期间接受新华社记者专访时表示，全球卫生体系正面临多重危机，而中国在基层医疗、数字健康、卫生体系规模化发展以及国际卫生合作等方面的实践经验，可为构建更具韧性的全球卫生体系提供有益启示。 这是2026年10月12日在德国首都柏林拍摄的世界卫生峰会首席执行官卡斯滕·席克尔。新华社记者 张豪夫 摄 世界卫生峰会从2009年起每年在柏林举办一次，旨在促进科研、政治、产业等方面的专家开展交流，通过加强伙伴关系和国际合…"
