    "author": "包雪琳",
    "description": "新华社北京10月13日电 东盟轮值主席国菲律宾13日确认，东南亚国家将在下月东盟峰会前夕举行的外长预备会议上探讨跨境烟霾治理。印度尼西亚多地近期林火和烟霾持续，一些地区空气质量达到“危险”级别。烟霾还跨境波及邻国，新加坡、马来西亚首都吉隆坡最近成为全球空气污染最为严重的城市。 马来西亚外交部长穆罕默德·哈山12日说，东南亚国家需要特别关注跨境烟霾，东盟应对自然灾害的现有机制尚未把跨境烟霾列为需要解决的问题。“我个人将在（外长预备）会上提…",
    "content": "新华社北京10月13日电 东盟轮值主席国菲律宾13日确认，东南亚国家将在下月东盟峰会前夕举行的外长预备会议上探讨跨境烟霾治理。印度尼西亚多地近期林火和烟霾持续，一些地区空气质量达到“危险”级别。烟霾还跨境波及邻国，新加坡、马来西亚首都吉隆坡最近成为全球空气污染最为严重的城市。 马来西亚外交部长穆罕默德·哈山12日说，东南亚国家需要特别关注跨境烟霾，东盟应对自然灾害的现有机制尚未把跨境烟霾列为需要解决的问题。“我个人将在（外长预备）会上提出这个问题与同事们探讨。” 10月9日，在马来西亚首都吉隆坡，马来西亚国家石油公…"
