    "description": "2026年10月14日 新华社记者 谢环驰摄 \"> 新华社记者 岳月伟摄 \"> 本报北京10月13日电 （记者杨翘楚）10月13日下午，国家主席习近平在北京人民大会堂同来华进行国事访问的博茨瓦纳总统博科举行会谈。两国元首宣布将双边关系提升为全面战略合作伙伴关系。 习近平指出，上世纪70年代，博方在两国建交前就投票支持新中国恢复在联合国合法席位。如今双方在共逐现代化梦想道路上携手前行，续写中博友谊新篇章。中博友谊要像钻石般璀璨恒久。双方要…",
