    "content": "2026年10月14日 本报北京10月13日电&nbsp;&nbsp;（记者褚君）继中国治沙人殷玉珍与美国友人赛考斯“跨国治沙”的感人故事引发中美民众强烈共鸣后，近期，美国人柏大卫与中国青海省湟源县的交往故事也引发广泛关注。外交部发言人毛宁13日表示，中方支持两国民间加强交往。 “中美民间友好是两国人民共同参与的事业。”毛宁介绍，美国人柏大卫如今已经95岁高龄。他曾在青海省湟源县生活17年，将湟源视为故乡，为当地筹赠医疗设备、捐资助学，并为英语教师赴美培训牵线搭桥。柏大卫谦逊地说，他的所作所为只是“给自家人尽本分”…"
