    "author": "",
    "description": "2026年10月14日 吉林延吉，延边大学对面的一座商业楼外墙上，70多块中文、朝鲜文双语招牌错落排布。入夜，灯光映亮店名，仿佛一条条“弹幕”铺满墙面，吸引游客驻足拍照。规范的双语表达便于识店寻路，模样各异的招牌又充满地方韵味。一面墙，就这样成为人们认识一座城的窗口。 街头的文字、衣裳的纹样、耳畔的乡音，一方水土孕育的文化，常常藏在寻常生活里。它们如何跨越地域、走近更多人？延吉的街景启发我们，地方特色文化的生命力，来自深厚的积淀，也来自…",
    "content": "2026年10月14日 吉林延吉，延边大学对面的一座商业楼外墙上，70多块中文、朝鲜文双语招牌错落排布。入夜，灯光映亮店名，仿佛一条条“弹幕”铺满墙面，吸引游客驻足拍照。规范的双语表达便于识店寻路，模样各异的招牌又充满地方韵味。一面墙，就这样成为人们认识一座城的窗口。 街头的文字、衣裳的纹样、耳畔的乡音，一方水土孕育的文化，常常藏在寻常生活里。它们如何跨越地域、走近更多人？延吉的街景启发我们，地方特色文化的生命力，来自深厚的积淀，也来自与当下生活相适应、与不同人群相交流的能力。 传统在今天有用武之地，传承才有绵长的…"
