    "content": "2026年10月14日 宁夏固原，学生们在将台堡红军长征会师纪念园的三军会师纪念馆内参观。 新华社记者 刘 昀摄 \"> 陕西吴起县中央红军长征胜利纪念园，各地游客与研学团队纷至沓来；中国人民革命军事博物馆“伟大的远征——纪念中国工农红军长征胜利90周年主题展览”上，战役场景让观众身临其境……今年以来，长征相关红色文旅热度攀升，人们在重温峥嵘岁月中汲取前行力量。 这正是： 关山万里烽烟远， 而今登临感万端。 且从故迹抒壮志， 长风浩荡更向前。 成&nbsp;&nbsp;森文 2026-10-14 00:00:00:0…"
