    "description": "2026年10月14日 本报记者 赵帅杰摄 \"> 太阳斜挂山坡，泛起红晕，就在村民们结束劳作、收工回家的时候，农村公益电影放映员李全民戴上头盔、发动三轮摩托车，载着陪伴他多年的放映机“开工”了。 李全民家住河南省鹤壁市鹤山区鹤壁集镇东头村，从1986年开始，他坚持为村民放映电影，至今已持续40年。 这些年，放映设备有更迭、负责区域有调整、观影群众有变化，身边的同行更是换了一茬又一茬，但电影放映工作从未间断。如今，62岁的他累计放映电影超…",
    "content": "2026年10月14日 李全民在放映电影。 本报记者 赵帅杰摄 \"> 太阳斜挂山坡，泛起红晕，就在村民们结束劳作、收工回家的时候，农村公益电影放映员李全民戴上头盔、发动三轮摩托车，载着陪伴他多年的放映机“开工”了。 李全民家住河南省鹤壁市鹤山区鹤壁集镇东头村，从1986年开始，他坚持为村民放映电影，至今已持续40年。 这些年，放映设备有更迭、负责区域有调整、观影群众有变化，身边的同行更是换了一茬又一茬，但电影放映工作从未间断。如今，62岁的他累计放映电影超1.2万场，惠及群众30余万人次。 “无论多晚，只要有放映安…"
