    "description": "2026年10月14日 本报北京10月13日电 （记者潘俊强）近日，首都绿化委员会印发了《首都古树名木保护高质量发展行动方案（2026—2030年）》。 根据该方案，北京正式启动首都古树名木保护管理体系优化提升行动、古树名木保护精准提质升级行动、古树名木保护科技创新赋能行动和古树名木文化传承与活化利用行动，明确未来5年全市古树名木保护的目标任务与实施路径。力争到2030年，北京将搭建1个标准化古树名木资源数据库，打造10处老城古树生态文…",
    "content": "2026年10月14日 本报北京10月13日电&nbsp;&nbsp;（记者潘俊强）近日，首都绿化委员会印发了《首都古树名木保护高质量发展行动方案（2026—2030年）》。 根据该方案，北京正式启动首都古树名木保护管理体系优化提升行动、古树名木保护精准提质升级行动、古树名木保护科技创新赋能行动和古树名木文化传承与活化利用行动，明确未来5年全市古树名木保护的目标任务与实施路径。力争到2030年，北京将搭建1个标准化古树名木资源数据库，打造10处老城古树生态文化地标，建设100处古树生境花园、古树村庄，对3000余株…"
