    "description": "2026年10月14日 本报北京10月13日电 （记者李卓尔）10月13日，中国社会科学院第二届青年学术大会在京召开。中国社会科学院院长、党组书记高翔出席会议并作学术报告。 会议以“传承·创新·规范”为主题，设置主论坛与学习贯彻习近平党建思想、人工智能辅助科研、全球文明研究、以“两个结合”推进理论创新、高质量发展、全面依法治国、区域国别研究、科教融合8个分论坛。会议发布了党的二十大以来中国社会科学院青年学者重要成果。院党组成员为2026…",
    "content": "2026年10月14日 本报北京10月13日电&nbsp;&nbsp;（记者李卓尔）10月13日，中国社会科学院第二届青年学术大会在京召开。中国社会科学院院长、党组书记高翔出席会议并作学术报告。 会议以“传承·创新·规范”为主题，设置主论坛与学习贯彻习近平党建思想、人工智能辅助科研、全球文明研究、以“两个结合”推进理论创新、高质量发展、全面依法治国、区域国别研究、科教融合8个分论坛。会议发布了党的二十大以来中国社会科学院青年学者重要成果。院党组成员为2026年度社科青年返乡调研“优秀调研报告奖”和“优秀组织奖”获奖…"
