    "description": "2026年10月14日 本报拉萨10月13日电 （记者徐驭尧）13日，农业农村部食物与营养发展研究所与西藏自治区农牧科学院在拉萨联合举办高原地区居民膳食营养与健康改善研讨会。研讨会聚焦改善高原居民膳食营养健康，围绕专项工作成效、经验推广、面临的短板挑战和下一步推进思路等深入研讨交流。 会议认为，西藏居民膳食营养健康改善专项工作构建了协同机制，形成了科学推进思路，编制了系列研究报告和指南规划，研发推广了系列共性关键技术，开展了整村试点示范…",
    "content": "2026年10月14日 本报拉萨10月13日电&nbsp;&nbsp;（记者徐驭尧）13日，农业农村部食物与营养发展研究所与西藏自治区农牧科学院在拉萨联合举办高原地区居民膳食营养与健康改善研讨会。研讨会聚焦改善高原居民膳食营养健康，围绕专项工作成效、经验推广、面临的短板挑战和下一步推进思路等深入研讨交流。 会议认为，西藏居民膳食营养健康改善专项工作构建了协同机制，形成了科学推进思路，编制了系列研究报告和指南规划，研发推广了系列共性关键技术，开展了整村试点示范与科普宣传引导，形成了可复制可推广的经验。 与会人员认为，…"
