    "description": "2026年10月14日 清晨，薄雾轻笼林梢。 辽宁省阜新市彰武县章古台林场阿尔乡护林点，62岁的护林员李东魁迈步出门，脚下沙地细软。三十九载寒来暑往，他日复一日巡护在8500多亩樟子松林间。 “沙地种出来的西瓜和花生甜度高、品相好。”护林点5公里外，阿尔乡镇阿尔乡村，李东魁的女儿——37岁的村支书李明明走进大棚查看果蔬长势。从林业院校毕业回乡，她立志守护绿色、盘活沙地，“通过改良土壤、管控水肥，昔日飞沙走石的荒滩正结出累累硕果，村集体经…",
    "content": "2026年10月14日 清晨，薄雾轻笼林梢。 辽宁省阜新市彰武县章古台林场阿尔乡护林点，62岁的护林员李东魁迈步出门，脚下沙地细软。三十九载寒来暑往，他日复一日巡护在8500多亩樟子松林间。 “沙地种出来的西瓜和花生甜度高、品相好。”护林点5公里外，阿尔乡镇阿尔乡村，李东魁的女儿——37岁的村支书李明明走进大棚查看果蔬长势。从林业院校毕业回乡，她立志守护绿色、盘活沙地，“通过改良土壤、管控水肥，昔日飞沙走石的荒滩正结出累累硕果，村集体经济收入连续4年超100万元。” 从一棵树到整片林海，70余年接力治沙，曾经沙化面…"
