    "description": "2026年10月14日 重庆市开州区鲁渝（寿光）蔬菜现代产业园，种植户谭世富拨开辣椒叶片，仔细察看长势。眼前的辣椒，和他过去种的不太一样。藤蔓沿着吊绳向上攀爬，长到两米多高，一茬苗可以采收更长时间。“没想过辣椒还能这么种。”谭世富说。 过去，他种辣椒靠的是多年积累的经验。什么时候浇水、什么时候施肥，大多凭感觉。白粉虱、蚜虫、蓟马等害虫来了，有时等叶片已经显出病斑才发现。如今，修枝、留果、控水、控肥、防治病虫害，他一样样重新学起。教他的人…",
    "content": "2026年10月14日 重庆市开州区鲁渝（寿光）蔬菜现代产业园，种植户谭世富拨开辣椒叶片，仔细察看长势。眼前的辣椒，和他过去种的不太一样。藤蔓沿着吊绳向上攀爬，长到两米多高，一茬苗可以采收更长时间。“没想过辣椒还能这么种。”谭世富说。 过去，他种辣椒靠的是多年积累的经验。什么时候浇水、什么时候施肥，大多凭感觉。白粉虱、蚜虫、蓟马等害虫来了，有时等叶片已经显出病斑才发现。如今，修枝、留果、控水、控肥、防治病虫害，他一样样重新学起。教他的人，来自1400多公里外的山东寿光。 技术跨过山海而来，不只改变了大棚和果园。有人…"
