    "description": "2026年10月14日 本报北京10月13日电 （记者王观）记者12日从国家税务总局获悉：今年前9个月，税务部门共停止公布失信主体12028户，其中，除依规到期自动停止公布外，1219户失信主体通过缴清税款、滞纳金、罚款共计13.55亿元后，申请提前停止公布，实现信用修复，修复总量同比增长30.93%。 据悉，2021年，税务总局修订发布《重大税收违法失信主体信息公布管理办法》，办法明确失信主体按照《税务处理决定书》《税务行政处罚决定书…",
    "content": "2026年10月14日 本报北京10月13日电&nbsp;&nbsp;（记者王观）记者12日从国家税务总局获悉：今年前9个月，税务部门共停止公布失信主体12028户，其中，除依规到期自动停止公布外，1219户失信主体通过缴清税款、滞纳金、罚款共计13.55亿元后，申请提前停止公布，实现信用修复，修复总量同比增长30.93%。 据悉，2021年，税务总局修订发布《重大税收违法失信主体信息公布管理办法》，办法明确失信主体按照《税务处理决定书》《税务行政处罚决定书》缴清（退）税款、滞纳金、罚款，且失信主体失信信息公布满六…"
