    "pub_date": "2026-10-14 08:26:03",
    "author": "",
    "description": "2026年10月14日 本报北京10月13日电 （记者常钦）经国务院批准，自然资源部会同国家发展改革委近日发布《矿产资源目录》。 矿产资源目录是矿产资源管理制度的重要基础，是制定矿产资源规划、实施矿业权管理、规范矿产资源勘查开采行为、征缴矿产资源税费、制定产业政策等工作的依据。将矿产资源进行科学划分，建立矿产资源目录，为矿产资源“上户口”具有重要意义。 为贯彻落实新矿产资源法以及实施条例，自然资源部会同国家发展改革委等部门，在原《矿产资…",
    "content": "2026年10月14日 本报北京10月13日电&nbsp;&nbsp;（记者常钦）经国务院批准，自然资源部会同国家发展改革委近日发布《矿产资源目录》。 矿产资源目录是矿产资源管理制度的重要基础，是制定矿产资源规划、实施矿业权管理、规范矿产资源勘查开采行为、征缴矿产资源税费、制定产业政策等工作的依据。将矿产资源进行科学划分，建立矿产资源目录，为矿产资源“上户口”具有重要意义。 为贯彻落实新矿产资源法以及实施条例，自然资源部会同国家发展改革委等部门，在原《矿产资源分类细目》的基础上，优化调整形成了《矿产资源目录》。为保…"
