    "description": "2026年10月14日 新疆维吾尔自治区巴音郭楞蒙古自治州博湖县，田间地头、乡间道路、工厂车间里，铺展出一片片火红。当地辣椒种植户抢抓眼下晴好天气，加紧晾晒辣椒。新鲜辣椒经过晾晒、分拣、装袋后，送到工厂加工，变成辣椒丝、辣椒酱、火锅底料等产品。 博湖县塔温觉肯乡村民孙厚起种植鲜食辣椒已有20多年。“今年种了50多亩辣椒，预计能产干辣椒20多吨，年初跟企业签了收购订单，不担心销路。”孙厚起介绍，采用北斗导航自动驾驶移栽机栽种辣椒，同时用无…",
    "content": "2026年10月14日 新疆维吾尔自治区巴音郭楞蒙古自治州博湖县，田间地头、乡间道路、工厂车间里，铺展出一片片火红。当地辣椒种植户抢抓眼下晴好天气，加紧晾晒辣椒。新鲜辣椒经过晾晒、分拣、装袋后，送到工厂加工，变成辣椒丝、辣椒酱、火锅底料等产品。 博湖县塔温觉肯乡村民孙厚起种植鲜食辣椒已有20多年。“今年种了50多亩辣椒，预计能产干辣椒20多吨，年初跟企业签了收购订单，不担心销路。”孙厚起介绍，采用北斗导航自动驾驶移栽机栽种辣椒，同时用无人机植保，田间管理更加精准高效省力。 随着辣椒进入收获期，博湖县的辣椒加工企业也…"
