    "description": "2026年10月14日 本报雄安10月13日电 （记者邵玉姿）依托河北雄安新区住房管理中心与中央国家机关住房资金管理中心紧密协同、联动协作，中央国家机关住房公积金业务窗口正式进驻雄安新区公积金服务网点，有效打通京雄公积金服务壁垒，推动住房公积金京雄同城化服务提质升级。 两地住房公积金管理部门深化政务服务协作，推动国管直付公积金服务端口下沉至雄安本地。此后，新区疏解单位及缴存职工可在本地网点一站式办理各类国管住房公积金业务。通过两地数据共…",
    "content": "2026年10月14日 本报雄安10月13日电&nbsp;&nbsp;（记者邵玉姿）依托河北雄安新区住房管理中心与中央国家机关住房资金管理中心紧密协同、联动协作，中央国家机关住房公积金业务窗口正式进驻雄安新区公积金服务网点，有效打通京雄公积金服务壁垒，推动住房公积金京雄同城化服务提质升级。 两地住房公积金管理部门深化政务服务协作，推动国管直付公积金服务端口下沉至雄安本地。此后，新区疏解单位及缴存职工可在本地网点一站式办理各类国管住房公积金业务。通过两地数据共享，实现“就近办、便捷办”，落实“数据多跑路、群众少跑腿”…"
