    "content": "2026年10月14日 本报北京10月13日电&nbsp;&nbsp;（记者魏哲哲）福建省泉州市中级人民法院和南安市人民法院13日一审公开宣判魏家犯罪集团系列案。对魏怀仁、陈大卫、廖景芳3名被告人判处死刑；对魏青涛、康敏、熊恒星3名被告人判处无期徒刑，对苏红相、邓子达、陈龙江等55名被告人分别判处二十四年至三年三个月不等有期徒刑，并相应判处罚金、没收财产、驱逐出境等附加刑。 经审理查明，2019年以来，以魏怀仁、魏青松（另案处理）等为首要分子，亲信下属陈龙江及武装力量头目茶贵成、颜龙帝（均另案处理）等为重要成员的魏…"
