    "description": "2026年10月14日 对话嘉宾： 中国教育科学研究院数字教育研究所所长、研究员 曹培杰 复旦大学计算与智能创新学院教授 肖仰华 教育科技公司AI学习业务负责人 程 飞 北京邮电大学计算机技术专业研一学生 高德润 我的大学阶段是在AI（人工智能）大模型环境中度过的。过去，遇到不懂的概念，大家会去翻教材、问老师；后来，会打开搜索引擎输入关键词检索；现在，更多人习惯了用AI工具“一键求答”。AI时代的教育，不再停留于“会不会算”，而是逐步转…",
    "content": "2026年10月14日 对话嘉宾： 中国教育科学研究院数字教育研究所所长、研究员&nbsp;&nbsp;曹培杰 复旦大学计算与智能创新学院教授&nbsp;&nbsp;肖仰华 教育科技公司AI学习业务负责人&nbsp;&nbsp;程&nbsp;&nbsp;飞 北京邮电大学计算机技术专业研一学生&nbsp;&nbsp;高德润 我的大学阶段是在AI（人工智能）大模型环境中度过的。过去，遇到不懂的概念，大家会去翻教材、问老师；后来，会打开搜索引擎输入关键词检索；现在，更多人习惯了用AI工具“一键求答”。AI时代的教育，不再…"
