    "content": "2026年10月14日 10月13日，安徽省合肥市四河小学组织学生走进安徽省农业科学院水稻种植研究基地，开展“稻田课堂&nbsp;&nbsp;画秋丰收”主题实践活动。孩子们以稻田为天然画室，用画笔描摹金黄稻浪、斑斓秋色，沉浸式感受丰收气息。图为师生在稻田里“画秋”。 赵&nbsp;&nbsp;明摄（影像中国） 2026-10-14 00:00:00:0 30185527 1 0 http://paper.people.com.cn/rmrb/pc/content/202610/14/content_30185527…"
