    "content": "2026年10月14日 10月5日晚，辽宁大连梭鱼湾足球场，首届东北地区城市足球联赛（以下简称“东北超”）决赛举行。经激烈角逐，长春队以1∶0战胜大连队，获得首届“东北超”冠军。 赛场外，“东北超”把各地的赛场、演出、景区、商圈等串联在一起。从5月份揭幕到10月份收官，辽宁、吉林、黑龙江、内蒙古四省区共同参与，8个参赛城市、34场比赛、136天赛程，跨区域的文体旅商市场通过赛事紧密联结，融合共赢。 各地主场在赛前和中场休息期间，将展现地域特色和时代特征的文艺演出带入球赛现场。辽宁沈阳主场对阵黑龙江哈尔滨，来自沈飞、…"
