    "description": "2026年10月14日 本报杭州10月13日电 （记者江南）浙江省教育厅等七部门日前联合发布指导意见，要求加快学前特殊教育高质量发展，构建康教融合的学前特殊教育普惠体系。 浙江省教育厅基础教育处相关负责人表示，根据指导意见，全省普惠性幼儿园应按照“就近就便”原则接收适龄特殊儿童入园，包括孤独症谱系障碍、语言发展障碍等类别；支持有条件的地方创办专门的特殊教育幼儿园。 2026-10-14 00:00:00:0 30185529 10htt…",
