    "author": "",
    "description": "2026年10月14日 傍晚时分，广东省广州市越秀区建设大马路拥翠小区旁热闹起来，老人沿着缓坡散步，孩子在空地上嬉戏，茶铺飘出茗香，咖啡厅外坐着闲聊的年轻人。 这是一处经过改造后的林下活动空间，林荫与烟火气相映成趣。广州市城市规划勘测设计研究院有限公司总规划师胡峰和社区工作人员对着图纸，一一对照眼前已经落地的设计效果。“作为广州社区设计师队伍的一员，这些年一直在社区里跑，想的就是把设计做得更实用、更贴近大家的生活。现在我们这支专职队伍已…",
    "content": "2026年10月14日 傍晚时分，广东省广州市越秀区建设大马路拥翠小区旁热闹起来，老人沿着缓坡散步，孩子在空地上嬉戏，茶铺飘出茗香，咖啡厅外坐着闲聊的年轻人。 这是一处经过改造后的林下活动空间，林荫与烟火气相映成趣。广州市城市规划勘测设计研究院有限公司总规划师胡峰和社区工作人员对着图纸，一一对照眼前已经落地的设计效果。“作为广州社区设计师队伍的一员，这些年一直在社区里跑，想的就是把设计做得更实用、更贴近大家的生活。现在我们这支专职队伍已经有1700多人，全市177个镇街都有大家忙碌的身影。”胡峰说。 近年来，广州市…"
