    "content": "2026年10月14日 本报兰州10月13日电&nbsp;&nbsp;（记者曾亦辰）甘肃省人力资源和社会保障厅近日印发《甘肃省工伤康复管理办法》，进一步完善工伤保险预防、补偿、康复制度体系，为工伤职工康复救治提供制度遵循。 在康复实施模式上，设置早期介入与系统康复双路径。工伤职工临床治疗期间，同步开展康复干预，预防功能障碍、降低致残风险。工伤医疗（康复）协议机构及时评估康复潜力，制定早期介入方案，并经受伤职工或者其近亲属同意后实施。不具备康复条件的医疗机构可联合或转入康复机构开展服务。人社部门、协议机构同步告知工伤…"
