    "content": "2026年10月14日 本报北京10月13日电&nbsp;&nbsp;（记者李红梅）中国气象局近日公布《气象数据管理办法》，自今年11月1日起施行。 办法以“激励供给、促进流通、规范治理”为主线，构建了覆盖数据供给、数据流通利用、数据安全保障、监督管理、法律责任等全链条的制度框架。办法对于进一步促进和规范气象数据管理活动、加强气象数据权益保护、加快气象数据有序流通和价值释放具有重要意义，将推动各行各业气象资源汇聚，让气象数据真正“跑起来、用起来”，形成服务经济社会发展的合力。 近年来，气象部门大力推进气象数据共享共…"
