    "description": "新华社基加利10月13日电（记者刘佑民 鞠银河）据卢旺达政府和世界一级方程式赛车锦标赛（F1）官方13日消息，卢旺达已与F1签署10年协议，从2030年代初起举办F1非洲大奖赛。这标志着F1赛事将在1993年之后首次重返非洲。 卢旺达总统卡加梅13日在卢首都基加利出席有关活动时说，卢旺达为能举办F1非洲大奖赛感到自豪。“三十多年来，这项世界顶级赛车锦标赛一直未曾造访非洲大陆，而这份协议将改变这一现状。” 根据协议，首场比赛将在位于卢旺达…",
    "content": "新华社基加利10月13日电（记者刘佑民 鞠银河）据卢旺达政府和世界一级方程式赛车锦标赛（F1）官方13日消息，卢旺达已与F1签署10年协议，从2030年代初起举办F1非洲大奖赛。这标志着F1赛事将在1993年之后首次重返非洲。 卢旺达总统卡加梅13日在卢首都基加利出席有关活动时说，卢旺达为能举办F1非洲大奖赛感到自豪。“三十多年来，这项世界顶级赛车锦标赛一直未曾造访非洲大陆，而这份协议将改变这一现状。” 根据协议，首场比赛将在位于卢旺达东方省布盖塞拉地区的新建专用赛道举行，该赛道预计将在2030年代初期建成。 布盖…"
