    "content": "新华社利雅得10月14日电（记者罗晨 王海洲）沙特阿拉伯主导的多国联军发言人图尔基·马利基13日晚在社交媒体连发多条帖文称，联军当天已拦截并摧毁射向沙特境内的6枚导弹和3架无人机。据沙特民防部门消息，导弹拦截碎片造成人员受伤、建筑受损。 马利基说，也门胡塞武装向沙特东部城市哈拉德和宰赫兰分别发射一枚弹道导弹，被联军拦截。此外，联军在利雅得省和沙特南部地区拦截4枚巡航导弹和3架无人机。 新华社记者当晚在沙特首都利雅得听到爆炸声。另据目击者称，当晚在靠近宰赫兰的东部城市达曼听到爆炸声。沙特国家预警平台当晚向利雅得市和东…"
