    "description": "新华社德黑兰10月13日电（记者沙达提）伊朗外交部13日发表声明表示，当天召见英国驻伊朗大使雨果·肖特，抗议英国政府关于伊朗涉嫌参与英国皇家空军费尔福德基地事件的“毫无根据”的指控。 此前一天，英国首相伯纳姆在议会下院发表讲话时表示，英国皇家空军费尔福德基地事件“极有可能”在伊朗境内协调策划，“几乎可以肯定”是由伊朗伊斯兰革命卫队指挥。 伊朗外交部声明称，伊方对英国这种“不负责任和破坏性”做法表示强烈抗议，不接受英国政府“毫无根据”的指…",
    "content": "新华社德黑兰10月13日电（记者沙达提）伊朗外交部13日发表声明表示，当天召见英国驻伊朗大使雨果·肖特，抗议英国政府关于伊朗涉嫌参与英国皇家空军费尔福德基地事件的“毫无根据”的指控。 此前一天，英国首相伯纳姆在议会下院发表讲话时表示，英国皇家空军费尔福德基地事件“极有可能”在伊朗境内协调策划，“几乎可以肯定”是由伊朗伊斯兰革命卫队指挥。 伊朗外交部声明称，伊方对英国这种“不负责任和破坏性”做法表示强烈抗议，不接受英国政府“毫无根据”的指控。伊方要求英国政府尽快提供支持其反伊朗指控的文件和证据，否则伊朗将重新考虑与伦…"
