    "content": "新华社科威特城10月13日电（记者尹炣）萨那消息：据也门胡塞武装控制的马西拉电视台13日报道，沙特阿拉伯主导的多国联军战机当天对也门西部荷台达省多处燃油设施发动空袭，造成2人死亡、2人受伤。 一名也门安全部门官员当日告诉新华社记者，沙特联军战机对胡塞武装控制的荷台达省红海沿岸伊萨角地区多处燃油储存设施发动多次空袭。联军战机还袭击了荷台达省巴吉勒地区的燃油供应仓库。目前尚不清楚遭袭设施的受损程度。 当地居民告诉新华社记者，空袭后，遭袭地区升起滚滚黑烟。 荷台达省遭袭数小时前，也门石油公司位于萨那西部萨巴哈地区的一处设…"
