    "content": "新华社耶路撒冷10月13日电（记者庞昕熠 王卓伦）以色列外交部13日发表声明说，以方恢复了同哥伦比亚间的自由贸易协定，此举标志着两国在重建关系方面迈出重要一步。 哥伦比亚总统德拉埃斯普列亚今年8月宣誓就职后，哥以关系开始回暖。以色列外交部长萨尔称，以方在短短两个月间就“扭转”了双边关系。 自2023年10月巴以新一轮冲突爆发以来，哥以两国关系急剧恶化。哥伦比亚时任总统佩特罗多次谴责以色列在加沙地带的军事行动。 2023年10月底，哥方宣布召回驻以大使。2024年5月，佩特罗宣布与以色列断绝外交关系，但双方保留领事业…"
