    "content": "新华社大马士革10月13日电（记者林建杰）据叙利亚国家电视台13日报道，叙中部哈马省农村地区3名道路安全人员当天遭不明身份人员袭击身亡。 报道援引安全部门消息人士的话说，叙安全部队已进入高度戒备状态，将跟进调查这一事件并追捕涉案人员。 总部设在英国的“叙利亚人权观察组织”说，这起事件发生在哈马省东部公路上，袭击者当时驾驶4辆摩托车。3名伤者已被送往医院接受治疗。 “叙利亚人权观察组织”报道，哈马省农村地区当天还发生另一起袭击事件。当地一检查站遭不明身份武装人员袭击，造成1人死亡、1人受伤。 目前，尚无组织或个人宣布…"
