    "content": "新华社纽约10月13日电 纽约股市三大股指13日下跌。 截至当天收盘，道琼斯工业平均指数比前一交易日下跌180.45点，收于51670.1点，跌幅为0.35%；标准普尔500种股票指数下跌1.79点，收于7805.45点，跌幅为0.02%；纳斯达克综合指数下跌41.52点，收于27204.38点，跌幅为0.15%。 板块方面，标普500指数十一大板块六跌五涨。医疗板块和金融板块分别以1.33%和0.41%的跌幅领跌，能源板块和通信服务板块分别以1.74%和0.88%的涨幅领涨。"
