    "content": "新华社柏林10月13日电（记者王海麟 车云龙）德国南部纽伦堡市的机场13日因一架客机发出劫机警报，暂停起降，警方出动特种部队一度封锁机场。涉事客机最终安全降落。 当天中午，一架从希腊科孚岛飞往纽伦堡的客机发出代码“7500”，该代码表示飞机遭到劫持。飞行员一度无法通过无线电与地面取得联系。 涉事客机隶属于土耳其科伦登航空公司，航班号为XR456。 纽伦堡警方一名发言人表示，无线电设备故障可能是此次事件的原因之一。现场检查未发现危险，机上乘客和飞行员均安然无恙。调查人员尚未公布更多细节。 纽伦堡机场发言人表示，事发后…"
